import { Icon } from "@/registry/p1/internal/icons";
import "./faq.css";

export interface FaqItem {
  q: string;
  a: string;
}
export interface FaqProps {
  heading: string;
  items: FaqItem[];
}

export function FaqRender({ heading, items }: FaqProps) {
  return (
    <div className="p1-faq p1-block">
      <div className="p1-faq__inner">
        {heading && <h2 className="p1-faq__heading">{heading}</h2>}
        <div className="p1-faq__list">
          {(items || []).map((item, i) => (
            <div key={i} className="p1-faq__item">
              <div className="p1-faq__question-row">
                <h3 className="p1-faq__question">{item.q}</h3>
                <Icon name="plus" className="p1-faq__icon" />
              </div>
              <p className="p1-faq__answer">{item.a}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { FaqRender, type FaqProps, type FaqItem } from "./faq";
export type { FaqProps, FaqItem };

export const FaqBlock: ComponentConfig<FaqProps> = {
  fields: {
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Section heading for the FAQ. E.g. Frequently asked questions." },
    },
    items: {
      type: "array" as const,
      arrayFields: {
        q: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "A common customer question. End with a question mark." },
        },
        a: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Clear, helpful answer. 1–3 sentences." },
        },
      },
      defaultItemProps: { q: "Question?", a: "Answer." },
      getItemSummary: (item: FaqItem) => item.q || "Question",
    },
  },
  defaultProps: {
    heading: "Frequently asked questions",
    items: [
      { q: "Do I need a developer to make changes?", a: "No. Anyone on your team can edit pages visually with ready-made blocks — no code required." },
      { q: "Can I use my own components?", a: "Yes. Developers can add custom blocks once, and the whole team can reuse them." },
      { q: "How do previews work?", a: "Every change gets a shareable preview link, so you can review before publishing." },
    ],
  },
  render: FaqRender,
};

export const meta = defineMeta({
  title: 'FAQ',
  description: 'Vertically stacked question-and-answer list with a section heading and icon-decorated rows; use for support or product FAQ sections.',
  categories: ["convert"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-icons"],
});

.p1-faq__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-narrow);
}

.p1-faq__heading {
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  margin-block-end: var(--p1-space-xl);
  text-align: center;
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-faq__heading { font-size: var(--p1-text-3xl); }
}

.p1-faq__list { border-block-start: 1px solid var(--p1-border); }

.p1-faq__item {
  border-block-end: 1px solid var(--p1-border);
  padding-block: var(--p1-space-md);
}

.p1-faq__question-row {
  align-items: start;
  display: flex;
  gap: var(--p1-space-md);
  justify-content: space-between;
}
.p1-faq__question {
  font-size: var(--p1-text-lg);
  font-weight: var(--p1-weight-bold);
  line-height: var(--p1-leading-tight);
}
.p1-faq__icon {
  block-size: 1.25rem;
  color: var(--p1-fg-muted);
  flex: none;
  inline-size: 1.25rem;
  margin-block-start: 0.25rem;
}

.p1-faq__answer {
  color: var(--p1-fg-muted);
  line-height: var(--p1-leading-normal);
  margin-block-start: var(--p1-space-sm);
  max-inline-size: 92%;
}

